import{_ as i,o as a,c as n,aj as e}from"./chunks/framework.BdtAaXf2.js";const t="/assets/image-20241221082306852.C7VghJX6.png",o=JSON.parse('{"title":"16-区间类型","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/16-区间类型/16-区间类型.md","filePath":"仓颉入门到实战/16-区间类型/16-区间类型.md","lastUpdated":1734741109000,"__rawMarkdown":"# 16-区间类型\\n\\n区间类型用于表示拥有固定步长的序列。作用是方便开发者获取一段特定范围的内容。它的用法包含三个值：\\n\\n1. start 表示开始\\n2. end 表示结束\\n3. step 表示步长\\n\\n比如：\\n\\n```javascript\\n0..4=1  // 0、1、2、3、4\\n```\\n\\n1. 0 表示开始\\n2. 4 表示结束\\n3. 1 表示步长\\n\\n所以结果表示 `0、1、2、3、4`\\n\\n区间类型字面量有两种形式\\n\\n1. 左闭右开\\n2. 左闭右闭\\n\\n这里的**闭**意思是包含、**开**表示不包含\\n\\n\\n\\n## 左闭右开\\n\\n```javascript\\nlet range1 = 0..4 : 1  // range1 = 0、1、2、3\\n```\\n\\n需要注意的是  区间类型不是数组，不能直接访问，也不能直接通过索引访问\\n\\n```javascript\\n    let range1 = 0..4 : 1 // range1 = 0、1、2、3\\n    println(range1) // expected \'Struct-String\', found \'Struct-Range<Int64>\'\\n```\\n\\n---\\n\\n```javascript\\n    let range1 = 0..4 : 1 // range1 = 0、1、2、3\\n\\n    println(range1[0]) // you may want to implement \'operator func [](index0: Int64)\' for type \'Struct-Range<Int64>\'\\n```\\n\\n**此时，我们可以通过遍历的方式来访问区间中的元素**\\n\\n```javascript\\n    let range1 = 0..4 : 1 // range1 = 0、1、2、3\\n    for (i in range1) {\\n        println(\\"The element is ${i}\\")\\n    }\\n```\\n\\n![image-20241221082306852](16-%E5%8C%BA%E9%97%B4%E7%B1%BB%E5%9E%8B.assets/image-20241221082306852.png)\\n\\n## 左闭右闭\\n\\n```javascript\\nlet range1 = 0..4 = 1  // range1 = 0、1、2、3、4\\n```\\n\\n\\n\\n## 总结\\n\\n1. 左闭右开 `0..4 : 1`   **0、1、2、3**\\n\\n2. 左闭右闭 `0..4 = 1`   **0、1、2、3、4**\\n\\n   "}'),l={name:"仓颉入门到实战/16-区间类型/16-区间类型.md"};function p(r,s,h,k,d,g){return a(),n("div",null,[...s[0]||(s[0]=[e("",23)])])}const u=i(l,[["render",p]]);export{o as __pageData,u as default};
